'use strict';
// Shared folder semantics for the library, picker and current analysis.
const v3Base={library,workbench,workset,pickerModal,handleAction,modalContent,render,persist,configPanel,makeResult,configurationFragment,validate};
const folderPath=p=>['全部资料','根目录',null,undefined].includes(p)?'':String(p).replace(/^\/+|\/+$/g,'');
const folderName=p=>folderPath(p).split('/').at(-1)||'全部资料';
const underFolder=(child,parent)=>!folderPath(parent)||folderPath(child)===folderPath(parent)||folderPath(child).startsWith(folderPath(parent)+'/');
const directoryKey=(space,path)=>space+'::'+folderPath(path);
const treeClosed=new Set();
const folderQueries={library:'',picker:''};
const toolColor={extract:'#396fce',word:'#238675',theme:'#7863b1',timeline:'#327f9b',risk:'#b87b24',meeting:'#a5657c',contract:'#3d8471',bidding:'#a87846',prepaid:'#5b70a9',engineering:'#577f9b',association:'#7963a7'};
state.directoryNodes??=[];
try{state.directoryNodes=JSON.parse(localStorage.getItem('audit-studio-directory-nodes')||'[]');}catch{}
persist=function(){v3Base.persist();try{localStorage.setItem('audit-studio-directory-nodes',JSON.stringify(state.directoryNodes));}catch{}};
// Upgrade demo directory paths only once; document IDs and existing task references stay stable.
if(!localStorage.getItem('audit-studio-tree-demo-v3')){
 const folders={d2:'根目录',d4:'会议纪要/专题会议',d5:'会议纪要/专题会议/验收',d12:'合同资料/设备采购/技术附件'};
 Object.entries(folders).forEach(([id,path])=>{const d=file(id);if(d)d.folder=path;});
 try{localStorage.setItem('audit-studio-tree-demo-v3','1');}catch{}
}
function directoryPaths(space,docs=null){
 const set=new Set();const paths=(docs||state.docs.filter(d=>!d.deleted&&d.space===space)).map(d=>d.folder);
 if(!docs)paths.push(...state.directoryNodes.filter(d=>d.space===space).map(d=>d.path),...(space==='项目空间'?(state.customFolders||[]):[]));
 paths.forEach(p=>{const seg=folderPath(p).split('/').filter(Boolean);seg.forEach((_,i)=>set.add(seg.slice(0,i+1).join('/')));});return [...set].sort((a,b)=>a.localeCompare(b,'zh-CN'));
}
function childDirectories(space,path,docs=null){const parent=folderPath(path);return directoryPaths(space,docs).filter(p=>p.split('/').slice(0,-1).join('/')===parent);}
function inDirectory(space,path,recursive=false,query='',docs=state.docs){return docs.filter(d=>!d.deleted&&d.space===space&&(recursive?underFolder(d.folder,path):folderPath(d.folder)===folderPath(path))&&d.name.toLowerCase().includes(query.toLowerCase()));}
function folderCrumbs(space,path,context){const seg=folderPath(path).split('/').filter(Boolean),action=context==='picker'?'picker-folder':'folder',project=state.projectName||'园区改造项目';return '<nav class="folder-crumbs" aria-label="当前目录">'+A(E(space),action,'data-id="全部资料"')+(space==='项目空间'&&seg[0]!==project?I('chevron','icon-sm')+A(E(project),action,'data-id="全部资料"'):'')+seg.map((s,i)=>I('chevron','icon-sm')+A(E(s),action,'data-id="'+E(seg.slice(0,i+1).join('/'))+'"')).join('')+'</nav>';}
function directoryNav(space,active,context,path='',depth=0){const action=context==='picker'?'picker-folder':'folder',query=folderQueries[context].trim().toLowerCase();return childDirectories(space,path).filter(p=>!query||directoryPaths(space).some(x=>underFolder(x,p)&&x.toLowerCase().includes(query))).map(p=>{const k=context+'::'+directoryKey(space,p),closed=!query&&treeClosed.has(k),hasChildren=childDirectories(space,p).length>0;return '<div class="dir-nav-line '+(folderPath(active)===p?'selected':'')+'" style="--depth:'+depth+'"><button class="tree-chevron" data-action="v3-toggle-dir" data-key="'+E(k)+'" '+(hasChildren?'aria-expanded="'+!closed+'"':'disabled')+' aria-label="展开或收起 '+E(folderName(p))+'">'+I(hasChildren?(closed?'chevron':'down'):'minus','icon-sm')+'</button><button class="dir-nav-name" data-action="'+action+'" data-id="'+E(p)+'" title="'+E(p)+'">'+I('folder','icon-sm')+'<span>'+E(folderName(p))+'</span></button></div>'+(!closed?directoryNav(space,active,context,p,depth+1):'');}).join('');}
function libraryItems(){const q=state.query||'',path=folderPath(state.folder),recursive=state.libraryRecursive||false;return [...(!q&&!recursive?childDirectories(state.space,path).map(path=>({kind:'folder',path})):[]),...inDirectory(state.space,path,recursive,q).map(file=>({kind:'file',file}))];}
function pickerItems(){const p=modalData,q=p.query||'',recursive=p.recursive||false;return [...(!q&&!recursive?childDirectories(p.space,p.folder).map(path=>({kind:'folder',path})):[]),...inDirectory(p.space,p.folder,recursive,q).filter(f=>!f.local&&(!p.table||f.rows)&&f.id!==p.main).map(file=>({kind:'file',file}))];}
function pageItems(items,page,size){return items.slice((page-1)*size,page*size);}
function mixedRows(items,context){const picker=context==='picker',p=modalData;return items.map(item=>{
 if(item.kind==='folder'){const path=item.path,space=picker?p.space:state.space,count=inDirectory(space,path,true).filter(f=>!f.local&&(!picker||!p.table||f.rows)).length;return '<tr class="folder-entry" data-folder-path="'+E(path)+'"><td>'+I('folder','folder-symbol')+'</td><td><button class="filename" data-action="'+(picker?'picker-folder':'folder')+'" data-id="'+E(path)+'">'+E(folderName(path))+'</button><div class="file-sub">文件夹 · '+count+' 份可用资料（含下级）</div></td><td>'+tag('文件夹')+'</td><td class="no-mobile">—</td><td>'+A('打开',picker?'picker-folder':'folder','data-id="'+E(path)+'"')+(!picker||p.table?'':' · '+A('选择范围','v3-picker-range','data-path="'+E(path)+'"'))+'</td></tr>';}
 const d=item.file,selected=picker?p.selected:state.librarySelected;return '<tr data-file-id="'+d.id+'"><td><input type="'+(picker&&p.table?'radio':'checkbox')+'" name="'+(picker?'picker-file':'library-file')+'" aria-label="选择 '+E(d.name)+'" data-change="'+(picker?'picker-check':'library-check')+'" data-id="'+d.id+'" '+(selected.includes(d.id)?'checked':'')+' '+(d.local?'disabled':'')+'></td><td><div class="row">'+ficon(d)+'<div class="grow">'+(picker?'<label class="filename" title="'+E(d.name)+'">'+E(d.name)+'</label>':'<button class="filename" data-action="source" data-id="'+d.id+'">'+E(d.name)+'</button>')+'<div class="file-sub">'+E(folderPath(d.folder)||'空间根目录')+'</div></div></div></td><td>'+tag(d.local?'待解析':'可分析',d.local?'amber':'green')+'</td><td class="no-mobile muted">'+E(d.size)+'</td><td>'+A('预览','source','data-id="'+d.id+'"')+(!picker?' · '+A('详情','file-detail','data-id="'+d.id+'"'):'')+'</td></tr>';
 }).join('');}
function mixedTable(items,context){const picker=context==='picker',selected=picker?modalData.selected:state.librarySelected,files=items.filter(x=>x.kind==='file'&&!x.file.local).map(x=>x.file),single=picker&&modalData.table;return '<div class="tablewrap mixed-table"><table class="table"><thead><tr><th><input type="checkbox" data-change="'+(picker?'picker-page':'library-page')+'" aria-label="选择本页文件，不含文件夹" '+(files.length&&files.every(f=>selected.includes(f.id))?'checked':'')+' '+(!files.length||single?'disabled':'')+'></th><th>名称</th><th>状态</th><th class="no-mobile">大小</th><th>操作</th></tr></thead><tbody>'+mixedRows(items,context)+'</tbody></table></div>';}
library=function(){const items=libraryItems(),pages=Math.max(1,Math.ceil(items.length/7));state.page=Math.max(1,Math.min(state.page,pages));const ds=pageItems(items,state.page,7);return '<div class="page library-v3"><div class="pagehead"><h1>资料管理</h1><div class="row">'+B(I('clock')+'上传记录','upload-records','sm')+B(I('upload')+'上传资料','upload','primary sm')+'</div></div><div class="library-layout"><section class="card"><div class="library-body"><nav class="folder-tree"><div class="row between mb">'+B(E(state.space)+I('down','icon-sm'),'space','sm')+'</div><input id="library-folder-search" class="tree-search" aria-label="搜索资料文件夹" placeholder="查找文件夹" data-v3-input="folder-search" data-context="library" value="'+E(folderQueries.library)+'">'+A(I('folder')+' 空间根目录','folder','data-id="全部资料"')+directoryNav(state.space,state.folder,'library')+B(I('plus')+'新建文件夹','new-folder','ghost sm mt')+'</nav><div class="file-pane"><div class="browser-toolbar">'+folderCrumbs(state.space,state.folder,'library')+'<div class="row"><div class="search">'+I('search')+'<input aria-label="搜索资料名称" placeholder="搜索文件" data-input="library-query" value="'+E(state.query)+'"></div><select aria-label="资料搜索范围" data-v3-change="library-scope"><option value="direct" '+(!state.libraryRecursive?'selected':'')+'>仅本级</option><option value="recursive" '+(state.libraryRecursive?'selected':'')+'>含子文件夹</option></select></div></div>'+(state.librarySelected.length?'<div class="selectionbar"><span>已选 '+state.librarySelected.length+' 份 · 跨目录保留</span><div class="row">'+A('查看已选','library-selected')+A('清空','library-clear')+'</div></div>':'')+mixedTable(ds,'library')+(!items.length?'<div class="compact-empty">此范围没有文件。可切换为“含子文件夹”，或上传资料。</div>':'')+'<div class="pagination"><span>'+items.length+' 项 · 文件夹与文件</span><div class="row">'+B('上一页','lib-prev','sm',state.page===1?'disabled':'')+'<span>'+state.page+' / '+pages+'</span>'+B('下一页','lib-next','sm',state.page>=pages?'disabled':'')+'</div></div></div></div></section><aside class="card tools-panel"><div class="cardhead"><h3>分析工具</h3>'+tag('11 项','blue')+'</div>'+['基础分析','审计专题','数据核对'].map(g=>'<div class="tool-group-title">'+g+'</div>'+TOOLS.filter(t=>t.group===g).map(t=>'<button class="tool-card" data-action="open-tool" data-id="'+t.id+'"><span class="tool-symbol" style="--tool-color:'+toolColor[t.id]+'">'+I(t.icon)+'</span><span class="grow"><h4>'+t.name+'</h4><p>'+t.desc+'</p></span>'+I('chevron','chev')+'</button>').join('')).join('')+'</aside></div></div>';};
pickerModal=function(){const p=modalData,items=pickerItems(),pages=Math.max(1,Math.ceil(items.length/7));p.page=Math.max(1,Math.min(p.page,pages));const onPage=pageItems(items,p.page,7),fileCount=items.filter(x=>x.kind==='file').length;return modalFrame(p.table?'选择表'+(p.slot==='A'?'一':'二'):p.main?'关联附件':p.bid?'添加'+(p.role==='tender'?'招标':'投标')+'资料':'添加资料','文件夹与文件同层浏览；选择暂存，确认后生效。','<div class="picker-layout"><aside class="picker-left"><select aria-label="资料空间" data-change="picker-space">'+options(SPACE_ORDER,p.space)+'</select><input id="picker-folder-search" class="tree-search" aria-label="搜索可选文件夹" placeholder="查找文件夹" data-v3-input="folder-search" data-context="picker" value="'+E(folderQueries.picker)+'">'+A(I('folder')+' 空间根目录','picker-folder','data-id="全部资料"')+directoryNav(p.space,p.folder,'picker')+'</aside><div class="picker-center"><div class="browser-toolbar">'+folderCrumbs(p.space,p.folder,'picker')+'<div class="row"><div class="search">'+I('search')+'<input id="picker-query" aria-label="搜索待添加文件" placeholder="搜索文件" data-input="picker-query" value="'+E(p.query||'')+'"></div><select aria-label="文件选择范围" data-v3-change="picker-scope"><option value="direct" '+(!p.recursive?'selected':'')+'>仅本级</option><option value="recursive" '+(p.recursive?'selected':'')+'>含子文件夹</option></select></div></div><div class="selectionbar"><span>'+fileCount+' 份可选文件'+(p.recursive?' · 含子文件夹':' · 仅本级')+'</span>'+(!p.table?'<div class="row">'+A('加入本目录','picker-directory')+A('选择所有页','picker-all')+'</div>':'单选一张表')+'</div>'+mixedTable(onPage,'picker')+(!items.length?'<div class="compact-empty">当前范围没有可选文件，已选清单仍保留。</div>':'')+'<div class="pagination"><span>'+p.page+' / '+pages+' 页 · '+items.length+' 项</span><div class="row">'+B('上页','picker-prev','sm',p.page<=1?'disabled':'')+B('下页','picker-next','sm',p.page>=pages?'disabled':'')+'</div></div></div><aside class="picker-right"><div class="row between"><h4 title="包含各目录的已选项，确认后生效">'+(p.main?'已选附件':p.table?'已选台账':p.bid?'已选'+(p.role==='tender'?'招标':'投标')+'资料':'已选资料')+' <strong>'+p.selected.length+'</strong> 份</h4>'+A('清空','v3-picker-clear')+'</div>'+selectedDocs(p.selected).map(f=>'<div class="picked-item"><span>'+E(f.name)+'<small>'+E(f.space+' / '+(folderPath(f.folder)||'根目录'))+'</small></span><button class="iconbtn" aria-label="取消选择 '+E(f.name)+'" data-action="picker-unselect" data-id="'+f.id+'">'+I('close','icon-sm')+'</button></div>').join('')+'</aside></div>','<span class="grow small muted">已选文件去重 · 预览不改变选择</span>'+B('取消','close-modal')+B(p.table?'确认此表':p.main?'确认关联 '+p.selected.length+' 份':'确认选择','confirm-picker','primary',p.selected.length?'':'disabled'),'',true);};
function workTree(space,path,docs,depth=0){return childDirectories(space,path,docs).map(p=>{const key='work::'+directoryKey(space,p),closed=!ws().treeQuery&&treeClosed.has(key),count=docs.filter(d=>underFolder(d.folder,p)).length;return '<div class="work-tree-folder" style="--depth:'+depth+'"><button class="tree-chevron" aria-expanded="'+!closed+'" data-action="v3-toggle-dir" data-key="'+E(key)+'" aria-label="展开或收起 '+E(folderName(p))+'">'+I(closed?'chevron':'down','icon-sm')+'</button><button class="tree-folder-title" data-action="v3-toggle-dir" data-key="'+E(key)+'" title="'+E(space+' / '+p)+'">'+I('folder','icon-sm')+'<span>'+E(folderName(p))+'</span><small>'+count+'</small></button><button class="iconbtn" aria-label="管理目录 '+E(p)+'" data-action="v3-folder-review" data-space="'+E(space)+'" data-path="'+E(p)+'">'+I('settings','icon-sm')+'</button></div>'+(!closed?workTree(space,p,docs,depth+1):'');}).join('')+docs.filter(d=>folderPath(d.folder)===folderPath(path)).map(d=>'<div class="work-file '+(ws().preview===d.id?'active':'')+'" style="--depth:'+depth+'">'+(manage?'<input type="checkbox" data-change="manage-check" data-id="'+d.id+'" aria-label="勾选移出 '+E(d.name)+'" '+(manageIds.includes(d.id)?'checked':'')+'>':ficon(d))+'<button class="filename" data-action="preview" data-id="'+d.id+'" title="'+E(d.name+' · '+d.space+' / '+(folderPath(d.folder)||'根目录'))+'">'+E(d.name)+'</button>'+(!isLocked()&&!manage?'<button class="iconbtn" aria-label="移出 '+E(d.name)+'" data-action="remove-file" data-id="'+d.id+'">'+I('close','icon-sm')+'</button>':'')+'</div>').join('');}
workset=function(){const ids=currentTask()?.ids||ws().ids,allDocs=selectedDocs(ids),q=ws().treeQuery||'',docs=allDocs.filter(d=>(d.name+' '+d.folder).toLowerCase().includes(q.toLowerCase())),spaces=[...new Set(docs.map(d=>d.space))].sort((a,b)=>SPACE_ORDER.indexOf(a)-SPACE_ORDER.indexOf(b));return '<aside class="workset"><div class="workset-top"><div class="row between"><h3>本次资料 <small>'+ids.length+'</small></h3>'+(!isLocked()?A(manage?'完成':'管理','manage'):'')+'</div>'+B(I('plus')+'添加资料','picker','w100 sm soft mt')+'<div class="search work-search">'+I('search')+'<input id="work-tree-search" data-v3-input="work-search" aria-label="查找本次资料" placeholder="查找文件或目录" value="'+E(q)+'"></div></div><div class="workset-list">'+(manage?'<div class="row manage-tools">'+A('全选','manage-all')+A('移出 '+manageIds.length+' 份','manage-remove')+'</div>':'')+spaces.map(s=>'<div class="work-space">'+E(s)+'</div>'+workTree(s,'',docs.filter(d=>d.space===s))).join('')+(!ids.length?'<div class="compact-empty">添加文件或整个目录<br>'+B('选择资料','picker','soft sm mt')+'</div>':'')+(ids.length&&!docs.length?'<div class="compact-empty">没有匹配资料；分析范围不变。</div>':'')+'</div><div class="scope-foot">'+I('file','icon-sm')+'<span>'+ids.length+' 份纳入分析 · 预览不改变范围</span></div></aside>';};
workbench=function(){const t=tool(state.toolId),w=ws(),task=currentTask(),base=document.createElement('div');base.innerHTML=v3Base.workbench();const head=base.querySelector('.workhead'),bar=document.createElement('div');bar.innerHTML=runbox();const buttons=[...bar.querySelectorAll('button')].map(x=>x.outerHTML).join('');base.querySelectorAll('.runbox').forEach(x=>x.remove());const phase=task?task.status==='running'?1:2:w.ids.length?1:0;head.innerHTML='<div class="work-heading">'+B(I('menu'),'mobile-nav','ghost mobile-menu','aria-label="打开导航"')+'<span class="tool-symbol" style="--tool-color:'+toolColor[t.id]+'">'+I(t.icon)+'</span><h1>'+t.name+'</h1></div><div class="inline-steps">'+['选资料','设要求','看结果'].map((s,i)=>'<span class="'+(phase===i?'active':phase>i?'done':'')+'">'+(phase>i?'✓':i+1)+' '+s+'</span>').join('<i>›</i>')+'</div><div class="command-actions"><span class="ready-count">'+(task?({running:'处理中',completed:'已完成',partial:'部分完成',failed:'执行失败',awaiting:'待填基数',stopped:'已停止'}[task.status]):w.ids.length+' 份资料'+(w.ids.length&&validate(false).length?' · 待完善':'') )+'</span>'+B(I('help'),'help','ghost sm','aria-label="工具使用说明"')+B(I('tasks')+'任务中心','nav-tasks','sm')+buttons+'</div>';head.classList.add('work-commandbar');base.querySelectorAll('.initial-help').forEach(x=>x.remove());return base.innerHTML;};
configPanel=function(){let html=v3Base.configPanel();if(state.toolId==='contract'){const c=currentConfig();html=html.replace('<div class="config-section">','<div class="contract-auto"><label class="row-radio"><input type="checkbox" data-config="autoAnalysis" '+(c.autoAnalysis?'checked':'')+' '+(isLocked()?'disabled':'')+'>自动分析</label><span title="补充模型自动分析，规则结果仍保留；不代表自动执行任务。">'+I('help','icon-sm')+'</span></div><div class="config-section">');}return html;};
configurationFragment=function(id,c){const result=v3Base.configurationFragment(id,c);if(id==='contract')result.parameter_settings={button:c.autoAnalysis?1:0};return result;};
makeResult=function(task){let rows=v3Base.makeResult(task);if(task.toolId==='contract'&&task.config.autoAnalysis)rows.push(...task.successIds.map(id=>({doc:id,title:file(id)?.title,check:'自动分析 · 履约资料核验',judgment:'待核验',excerpt:file(id)?.text?.split('\n')[2]||'',detail:'自动分析：结合验收记录和技术附件核实履约情况。本条不代替原规则检查。',criteria:'合同正文及关联技术附件',judgmentRule:'结合履约证据进一步核验，不据资料缺失直接作结论。',autoAnalysis:true})));return rows;};
modalContent=function(){if(modal==='v3-folder-range'){const p=modalData.picker,path=modalData.path,direct=inDirectory(p.space,path,false).filter(f=>!f.local&&f.id!==p.main).length,all=inDirectory(p.space,path,true).filter(f=>!f.local&&f.id!==p.main).length;return modalFrame('选择目录范围',E(p.space+' / '+(path||'根目录')),'<div class="column">'+B('仅本级文件 · '+direct+' 份','v3-range-direct')+B('本级及所有子文件夹 · '+all+' 份','v3-range-recursive')+'</div>',B('返回','v3-range-back'),'small');}
 if(modal==='v3-folder-review'){const {space,path}=modalData,docs=selectedDocs(currentTask()?.ids||ws().ids).filter(d=>d.space===space&&underFolder(d.folder,path));return modalFrame(E(folderName(path))+' · '+docs.length+' 份',E(space+' / '+path)+'，含子文件夹',simpleTable(['名称','所在目录','操作'],docs.map(d=>[E(d.name),E(d.folder),A('预览','source','data-id="'+d.id+'"')]),true),B('关闭','close-modal')+(isLocked()?'':B('选中这些文件以管理','v3-manage-directory','soft')),'medium');}return v3Base.modalContent();};
handleAction=function(action,el){const id=el?.dataset.id,p=modalData;switch(action){
 case 'v3-toggle-dir':{const key=el.dataset.key;treeClosed.has(key)?treeClosed.delete(key):treeClosed.add(key);modal==='picker'?paintModal():render();return;}
 case 'folder':case 'picker-folder':{const target=folderPath(id)||'全部资料';if(action==='folder'){state.folder=target;state.page=1;state.query='';render();}else{p.folder=target;p.page=1;p.query='';paintModal();}return;}
 case 'picker-all':p.selected=[...new Set([...p.selected,...pickerItems().filter(x=>x.kind==='file').map(x=>x.file.id)])];paintModal();return;
 case 'picker-directory':case 'v3-picker-range':openModal('v3-folder-range',{picker:structuredClone(p),path:folderPath(el.dataset.path??p.folder)});return;
 case 'v3-range-back':openModal('picker',p.picker);return;
 case 'v3-range-direct':case 'v3-range-recursive':{const next=p.picker;const ids=inDirectory(next.space,p.path,action==='v3-range-recursive').filter(f=>!f.local&&f.id!==next.main).map(f=>f.id);next.selected=[...new Set([...next.selected,...ids])];openModal('picker',next);return;}
 case 'v3-picker-clear':p.selected=[];paintModal();return;
 case 'v3-folder-review':openModal('v3-folder-review',{space:el.dataset.space,path:el.dataset.path});return;
 case 'v3-manage-directory':manageIds=selectedDocs(ws().ids).filter(d=>d.space===p.space&&underFolder(d.folder,p.path)).map(d=>d.id);manage=true;closeModal();render();return;
 case 'create-folder':{const name=$('#modal-text').value.trim(),parent=folderPath(state.folder);if(!name||/[\\/]/.test(name)||['.','..'].includes(name)){$('#modal-error').textContent='请输入文件夹名称，不含斜杠。';return;}const path=parent?parent+'/'+name:name;if(directoryPaths(state.space).includes(path)){$('#modal-error').textContent='此层已有同名文件夹。';return;}state.directoryNodes.push({space:state.space,path});state.folder=path;closeModal();render();toast('文件夹已在当前空间创建。');return;}
 case 'source':if(modal==='picker'){storePickerPreview=structuredClone(p);}break;
 }
 return v3Base.handleAction(action,el);
};
// Preview is a temporary detour; return to the same picker with selections intact.
let storePickerPreview=null;
const v3CloseModal=closeModal;
closeModal=function(){if(modal==='source'&&storePickerPreview){const p=storePickerPreview;storePickerPreview=null;openModal('picker',p);return;}v3CloseModal();};
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='library-page'||el.dataset.change==='picker-page'){e.stopImmediatePropagation();const picker=el.dataset.change==='picker-page',obj=picker?modalData:state,items=picker?pickerItems():libraryItems(),ids=pageItems(items,obj.page,7).filter(x=>x.kind==='file'&&!x.file.local).map(x=>x.file.id),old=picker?obj.selected:obj.librarySelected,next=el.checked?[...new Set([...old,...ids])]:old.filter(id=>!ids.includes(id));if(picker){obj.selected=next;paintModal();}else{obj.librarySelected=next;render();}return;}
 if(el.dataset.v3Change){e.stopImmediatePropagation();if(el.dataset.v3Change==='picker-scope'){modalData.recursive=el.value==='recursive';modalData.page=1;paintModal();}else{state.libraryRecursive=el.value==='recursive';state.page=1;render();}}
},true);
render=function(){v3Base.render();$$('[data-action="open-tool"]').forEach(el=>{el.style.setProperty('--tool-color',toolColor[el.dataset.id]);});};
render();

// User-visible searches are filters only and never rewrite execution scope.
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.v3Input)return;const pos=el.selectionStart,id=el.id;if(el.dataset.v3Input==='folder-search'){folderQueries[el.dataset.context]=el.value;modal==='picker'?paintModal():render();}else{ws().treeQuery=el.value;render();}const next=document.getElementById(id);next?.focus();try{next?.setSelectionRange(pos,pos);}catch{}});
validate=function(show=true){let errors=v3Base.validate(false);if(state.toolId==='contract'&&(ws().config.autoAnalysis||ws().config.contractType==='自动'))errors=errors.filter(x=>x!=='请至少选择一个关注点或检查规则');if(show&&errors.length)openModal('validation',{errors});return errors;};
// The original meeting screen also imports completed results. Keep it separate from analysis.
const v3ConfigWithContract=configPanel;
configPanel=function(){let html=v3ConfigWithContract();if(state.toolId==='meeting'&&!isLocked())html=html.replace('<div class="config-section">','<div class="meeting-import-action">'+B(I('upload')+'导入已有结果','v3-meeting-import','sm')+'</div><div class="config-section">');return html;};
const v3ModalWithTree=modalContent;
modalContent=function(){if(modal==='v3-meeting-import')return modalFrame('导入会议分析结果','导入后新建结果任务，不覆盖原任务。','<div class="field"><label for="meeting-import-file">选择会议分析结果文件（JSON / Excel）</label><input id="meeting-import-file" type="file" accept=".json,.xlsx" class="w100"></div><p class="hint">可导入会议分析结果，校验通过后新建结果任务。</p><div id="meeting-import-preview" class="mt"></div><div id="meeting-import-error" class="error"></div>',B('取消','close-modal')+B('确认导入','v3-meeting-import-save','primary',modalData.parsed?'':'disabled'),'medium');return v3ModalWithTree();};
const v3ActionWithTree=handleAction;
handleAction=function(action,el){if(action==='v3-meeting-import'){openModal('v3-meeting-import',{});return;}if(action==='v3-meeting-import-save'){
 const d=modalData.parsed;if(!d)return;const ids=[...new Set(d.results.map(r=>r.doc))],w=ws();
 const task={id:'T'+Date.now(),name:(d.task||'会议结果')+' · 导入',toolId:'meeting',ids,config:structuredClone(d.config),status:'completed',progress:100,created:new Date().toISOString(),phase:'导入完成',successIds:ids,failedIds:[],result:structuredClone(d.results),attachments:{},stopwords:[],newwords:[],chats:[],meetingRisk:false,imported:true};
 state.tasks.unshift(task);w.taskId=task.id;w.ids=ids;w.tab='result';w.subtab='regular';closeModal();render();toast('已导入为新任务，原任务保留。');return;
 }return v3ActionWithTree(action,el);};
document.addEventListener('change',async e=>{if(e.target.id!=='meeting-import-file')return;const f=e.target.files[0];if(!f)return;const currentModalData=modalData;try{
 if(f.size>10*1024*1024)throw Error('文件不能超过10MB');if(!f.name.toLowerCase().endsWith('.json'))throw Error('无法解析此文件，请检查工作表格式。');
 const raw=await f.text();if(/"(__proto__|constructor|prototype)"\s*:/.test(raw))throw Error('文件包含无效属性');const d=JSON.parse(raw);
 if(!d.config?.stages?.regular||!Array.isArray(d.results)||!d.results.length)throw Error('请选择有效的会议分析结果文件');validateImportedConfig('meeting',d.config);
 if(d.results.some(r=>!file(r.doc)||['title','date','topic','excerpt','amount','participants'].some(k=>typeof r[k]!=='string')||!Number.isInteger(r.agenda)))throw Error('议题字段或来源文件不完整，无法核验');
 if(modal!=='v3-meeting-import'||modalData!==currentModalData)return;modalData.parsed=d;paintModal();$('#meeting-import-preview').textContent=d.results.length+' 条议题 · '+new Set(d.results.map(r=>r.doc)).size+' 份来源资料 · 校验通过';
 }catch(err){if(modal!=='v3-meeting-import'||modalData!==currentModalData)return;modalData.parsed=null;paintModal();$('#meeting-import-error').textContent=err.message;}});
render();

const v3TaskArea=taskArea;
taskArea=function(task){let html=v3TaskArea(task);if(task.imported)html=html.replace('分析结果已生成','已导入会议结果');return html;};
render();
